function Logo({ inverse = false }: { inverse?: boolean }) { const { t } = useLocale(); return <Link href="/" className={`brand-logo flex items-center gap-3 ${inverse ? "text-white" : "text-[var(--ni-teal)]"}`}><img src={mark} className="h-10 w-10 rounded-xl object-contain" alt={t("brand.name")} /><span><span className="font-display text-xl font-semibold tracking-tight">{t("brand.name")}</span><span className="block text-[10px] uppercase tracking-[.24em] opacity-65">{t("brand.tagline")}</span></span></Link>; }
function Button({ children, href, variant = "primary", onClick, type = "submit", disabled = false, "data-testid": testId }: { children: React.ReactNode; href?: string; variant?: "primary" | "quiet" | "outline"; onClick?: () => void; type?: "button" | "submit"; disabled?: boolean; "data-testid"?: string }) { const cls = `brand-button inline-flex items-center justify-center gap-2 rounded-full px-5 py-3 text-sm font-semibold ${variant === "primary" ? "bg-[var(--ni-moss)] text-white shadow-[0_10px_24px_rgba(14,90,79,.18)] hover:-translate-y-0.5 hover:bg-[var(--ni-teal-soft)]" : variant === "outline" ? "border border-[var(--ni-sage-mid)] bg-transparent text-[var(--ni-moss)] hover:bg-[var(--ni-sage-soft)]" : "bg-[var(--ni-sage-soft)] text-[var(--ni-ink)] hover:bg-[var(--ni-sage)]"}${disabled ? " cursor-not-allowed opacity-60 hover:translate-y-0" : ""}`; return href ? <Link href={href} className={cls}>{children}</Link> : <button type={type} onClick={onClick} className={cls} disabled={disabled} data-testid={testId}>{children}</button>; }
function Pill({ children, tone = "sage" }: { children: React.ReactNode; tone?: "sage" | "gold" | "ink" }) { return <span className={`status-pill inline-flex items-center rounded-full px-3 py-1 text-[11px] font-bold uppercase tracking-[.13em] ${tone === "gold" ? "bg-[var(--ni-gold-soft)] text-[var(--ni-gold-ink)]" : tone === "ink" ? "bg-[var(--ni-sage-soft)] text-[var(--ni-ink)]" : "bg-[var(--ni-sage-soft)] text-[var(--ni-teal-soft)]"}`}>{children}</span>; }
function Header() { const [open, setOpen] = useState(false); const { t } = useLocale(); return <header className="site-header sticky top-0 z-40 border-b border-[var(--ni-sage)]/80 bg-[var(--ni-field)]/92 backdrop-blur-xl"><div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 lg:px-8"><Logo /><nav className="hidden items-center gap-7 text-sm font-semibold text-[var(--ni-moss-deep)] lg:flex"><Link href="/courses" className="hover:text-[var(--ni-moss)]">{t("nav.courses")}</Link><Link href="/teachers" className="hover:text-[var(--ni-moss)]">{t("nav.tutors")}</Link><Link href="/requirements" className="hover:text-[var(--ni-moss)]">{t("nav.requirements")}</Link><Link href="/how-it-works" className="hover:text-[var(--ni-moss)]">{t("nav.howItWorks")}</Link><Link href="/help/lms" className="hover:text-[var(--ni-moss)]">{t("nav.help")}</Link></nav><div className="hidden items-center gap-3 lg:flex"><LocaleSelector/><Link href="/login" className="px-3 py-2 text-sm font-semibold text-[var(--ni-ink)]">{t("nav.login")}</Link><Button href="/signup">{t("nav.join")} <ArrowRight size={15}/></Button></div><button className="rounded-full bg-[var(--ni-sage-soft)] p-2 lg:hidden" aria-label={open ? t("nav.closeMenu") : t("nav.openMenu")} onClick={() => setOpen(!open)}>{open ? <X size={20}/> : <Menu size={20}/>}</button></div>{open && <div className="border-t border-[var(--ni-sage)] bg-[var(--ni-field)] px-5 py-5 lg:hidden"><div className="flex flex-col gap-4 text-sm font-semibold"><Link href="/courses" onClick={() => setOpen(false)}>{t("nav.courses")}</Link><Link href="/teachers" onClick={() => setOpen(false)}>{t("nav.tutors")}</Link><Link href="/requirements" onClick={() => setOpen(false)}>{t("nav.requirements")}</Link><Link href="/how-it-works" onClick={() => setOpen(false)}>{t("nav.howItWorks")}</Link><Link href="/help/lms" onClick={() => setOpen(false)}>{t("nav.help")}</Link><Link href="/login" className="pt-2 text-[var(--ni-moss)]">{t("nav.login")}</Link><LocaleSelector compact/></div></div>}</header>; }
function Footer() { const { t } = useLocale(); return <footer className="site-footer bg-[var(--ni-teal)] text-[var(--ni-sage-soft)]"><div className="mx-auto grid max-w-7xl gap-10 px-5 py-14 lg:grid-cols-[1.3fr_1fr_1fr_1fr] lg:px-8"><div><Logo inverse/><p className="mt-5 max-w-xs text-sm leading-7 text-[var(--ni-sage-mid)]">Thoughtful Islamic learning, with a clearer path from curiosity to consistency.</p></div><div><p className="mb-4 text-xs font-bold uppercase tracking-[.18em] text-[var(--ni-gold-mid)]">{t("footer.explore")}</p><div className="flex flex-col gap-3 text-sm"><Link href="/courses">{t("nav.courses")}</Link><Link href="/teachers">{t("nav.tutors")}</Link><Link href="/requirements">{t("nav.requirements")}</Link><Link href="/contact-lms">{t("footer.contact")}</Link></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-[.18em] text-[var(--ni-gold-mid)]">{t("footer.learn")}</p><div className="flex flex-col gap-3 text-sm"><Link href="/how-it-works">{t("nav.howItWorks")}</Link><Link href="/about-lms">{t("brand.name")}</Link><Link href="/help/lms">{t("nav.help")}</Link><Link href="/about-lms">{t("footer.privacy")}</Link></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-[.18em] text-[var(--ni-gold-mid)]">{t("home.noorWay")}</p><p className="text-sm leading-6 text-[var(--ni-sage-mid)]">{t("footer.demo")}</p><Link href="/signup" className="mt-4 inline-flex text-sm font-bold text-white">{t("nav.join")} <ArrowRight size={15} className="ml-2"/></Link></div></div><div className="border-t border-white/10 px-5 py-5 text-center text-xs text-[var(--ni-sage-mid)]">© 2026 Noor Ilm · LMS foundation · Demo content is clearly labelled</div></footer>; }
function SectionHeading({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy?: string; action?: React.ReactNode }) { return <div className="mb-9 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-3 text-xs font-bold uppercase tracking-[.2em] text-[var(--ni-gold-ink)]">{eyebrow}</p><h2 className="font-display text-4xl leading-[1.04] tracking-tight text-[var(--ni-ink)] sm:text-5xl">{title}</h2>{copy && <p className="mt-4 max-w-xl text-base leading-7 text-[var(--ni-muted)]">{copy}</p>}</div>{action}</div>; }
function CourseCard({ course, index = 0 }: { course: typeof courses[number]; index?: number }) { return <Link href={`/courses/${course.slug}`} className="group overflow-hidden rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] shadow-[0_14px_40px_rgba(37,77,60,.06)] hover:-translate-y-1 hover:shadow-[0_18px_42px_rgba(37,77,60,.12)]"><div className="relative h-36 overflow-hidden" style={{ backgroundColor: index % 2 ? "var(--ni-sage-soft)" : "var(--ni-gold-soft)" }}><img src={courseVisuals[index % courseVisuals.length]} alt="" className="h-full w-full object-cover mix-blend-multiply opacity-75 transition duration-500 group-hover:scale-105"/><div className="absolute left-4 top-4"><Pill>{course.subject}</Pill></div><div className="absolute bottom-3 right-4 rounded-full bg-white/80 px-3 py-1 text-xs font-bold text-[var(--ni-ink)]">{course.duration}</div></div><div className="p-5"><div className="mb-3 flex items-center justify-between text-xs text-[var(--ni-muted)]"><span>{course.level}</span><span>{course.format}</span></div><h3 className="font-display text-2xl leading-tight text-[var(--ni-ink)]">{course.title}</h3><p className="mt-3 line-clamp-2 text-sm leading-6 text-[var(--ni-muted)]">{course.description}</p><div className="mt-5 flex items-center justify-between border-t border-[var(--ni-sage-soft)] pt-4 text-sm"><span className="font-semibold text-[var(--ni-moss-deep)]">{course.instructor.name}</span><ArrowRight size={17} className="text-[var(--ni-gold-ink)] transition group-hover:translate-x-1"/></div></div></Link>; }
function TutorCard({ instructor, index = 0 }: { instructor: typeof instructors[number]; index?: number }) { return <Link href={`/teachers/${instructor.slug}`} className="group rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-5 shadow-[0_14px_40px_rgba(37,77,60,.05)] hover:-translate-y-1"><div className="flex items-start gap-4"><div className="relative h-16 w-16 shrink-0 overflow-hidden rounded-2xl bg-[var(--ni-sage-soft)]"><img src={tutorVisuals[index % tutorVisuals.length]} alt="" className="h-full w-full object-cover"/><span className="absolute bottom-1 right-1 h-3 w-3 rounded-full border-2 border-white bg-[var(--ni-gold-ink)]"/></div><div><h3 className="font-display text-xl text-[var(--ni-ink)]">{instructor.name}</h3><p className="mt-1 text-xs text-[var(--ni-muted)]">{instructor.experience} · {instructor.availability.timezone}</p></div></div><div className="mt-5 flex flex-wrap gap-2">{instructor.subjects.map((s) => <Pill key={s.name}>{s.name}</Pill>)}</div><p className="mt-4 text-sm leading-6 text-[var(--ni-muted)]">{instructor.bio}</p><div className="mt-5 flex items-center justify-between border-t border-[var(--ni-sage-soft)] pt-4 text-xs font-semibold text-[var(--ni-sage-ink)]"><span>{instructor.languages.join(" · ")}</span><span className="text-[var(--ni-gold-ink)]">View profile <ArrowRight size={14} className="ml-1 inline"/></span></div></Link>; }
function Home() { const { t } = useLocale(); return <><Header/><main><section className="grain relative overflow-hidden bg-[var(--ni-bg)]"><div className="mx-auto grid max-w-7xl items-center gap-10 px-5 py-16 lg:grid-cols-[.82fr_1.18fr] lg:px-8 lg:py-24"><div className="relative z-10 reveal"><Pill tone="gold">{t("home.eyebrow")}</Pill><h1 className="text-balance mt-6 max-w-xl font-display text-6xl leading-[.96] tracking-[-.04em] text-[var(--ni-teal)] sm:text-7xl">{t("home.title")}</h1><p className="mt-7 max-w-lg text-lg leading-8 text-[var(--ni-muted)]">{t("home.copy")}</p><div className="mt-9 flex flex-wrap gap-3"><Button href="/courses">{t("home.exploreCourses")} <ArrowRight size={16}/></Button><Button href="/teachers" variant="outline">{t("home.findTutor")}</Button></div><p className="mt-6 text-xs font-semibold tracking-wide text-[var(--ni-muted)]">{t("home.readiness")}</p></div><div className="relative min-h-[380px] reveal reveal-delay-1 lg:min-h-[540px]"><div className="star-watermark absolute -right-6 -top-8 h-40 w-40 rounded-full opacity-80"/><div className="absolute inset-0 overflow-hidden rounded-[2rem] rounded-bl-[6rem] shadow-[0_24px_70px_rgba(33,78,57,.18)]"><img src={hero} alt="Learner studying in a calm, sunlit study room" className="h-full w-full object-cover"/><div className="absolute inset-0 bg-gradient-to-r from-[var(--ni-teal)]/20 via-transparent to-transparent"/></div><div className="absolute -bottom-6 -left-4 max-w-[220px] rounded-2xl border border-white/70 bg-[var(--ni-paper)]/95 p-4 shadow-xl backdrop-blur"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.15em] text-[var(--ni-gold-ink)]"><Sparkles size={14}/> {t("home.noorWay")}</div><p className="mt-2 font-display text-xl leading-tight text-[var(--ni-ink)]">{t("home.discoverConnect")}</p></div></div></div></section><section className="mx-auto max-w-7xl px-5 py-20 lg:px-8 lg:py-28"><SectionHeading eyebrow={t("home.studyDesk")} title={t("home.studyTitle")} copy={t("home.studyCopy")} action={<Button href="/courses" variant="quiet">{t("home.browseAll")} <ArrowRight size={16}/></Button>}/><div className="grid gap-5 md:grid-cols-2 lg:grid-cols-4">{courses.map((course, i) => <div key={course.slug} className={`reveal reveal-delay-${Math.min(i,3)}`}><CourseCard course={course} index={i}/></div>)}</div></section><section className="mx-auto max-w-7xl px-5 pb-20 lg:px-8"><div className="mb-8 flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[var(--ni-gold-ink)]">{t("home.popularSubjects")}</p><h2 className="mt-3 font-display text-4xl text-[var(--ni-ink)]">{t("home.chooseDoor")}</h2></div><Link href="/courses" className="text-sm font-bold text-[var(--ni-moss)]">{t("home.browseAll")} <ArrowRight size={15} className="ml-1 inline"/></Link></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">{["Quran Recitation","Tajweed","Hifz","Arabic","Hadith","Fiqh","Seerah","Tafsir","Noorani Qaida","Children’s learning"].map((category, i) => <Link href={`/courses?subject=${encodeURIComponent(category)}`} key={category} className="group border-t-2 border-[var(--ni-gold-ink)] bg-[var(--ni-sage-soft)] p-4 hover:bg-[var(--ni-sage)]"><span className="text-xs font-bold text-[var(--ni-gold-ink)]">0{i + 1}</span><span className="mt-8 block font-display text-xl leading-tight text-[var(--ni-ink)]">{category}</span><ArrowRight size={15} className="mt-5 text-[var(--ni-moss)] transition group-hover:translate-x-1"/></Link>)}</div></section><section className="bg-[var(--ni-teal)] text-white"><div className="mx-auto grid max-w-7xl gap-12 px-5 py-20 lg:grid-cols-[.7fr_1.3fr] lg:px-8 lg:py-24"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[var(--ni-gold-mid)]">{t("home.whyEyebrow")}</p><h2 className="mt-4 font-display text-5xl leading-[1.03]">{t("home.pathTitle")}</h2><p className="mt-5 max-w-md leading-7 text-[var(--ni-sage-mid)]">{t("home.pathCopy")}</p></div><div className="grid gap-4 sm:grid-cols-2"><div className="rounded-3xl bg-white/10 p-6"><Compass className="text-[var(--ni-gold-mid)]"/><h3 className="mt-8 font-display text-2xl">{t("home.findFit")}</h3><p className="mt-2 text-sm leading-6 text-[var(--ni-sage-mid)]">{t("home.findFitCopy")}</p></div><div className="rounded-3xl bg-[var(--ni-gold-soft)] p-6 text-[var(--ni-ink)]"><ShieldCheck className="text-[var(--ni-gold-ink)]"/><h3 className="mt-8 font-display text-2xl">{t("home.trust")}</h3><p className="mt-2 text-sm leading-6 text-[var(--ni-muted)]">{t("home.trustCopy")}</p></div><div className="rounded-3xl bg-white/10 p-6 sm:col-span-2"><div className="flex items-center gap-4"><div className="rounded-2xl bg-white/10 p-3"><CalendarDays className="text-[var(--ni-gold-mid)]"/></div><div><h3 className="font-display text-2xl">{t("home.tryCommit")}</h3><p className="mt-1 text-sm text-[var(--ni-sage-mid)]">{t("home.tryCopy")}</p></div></div></div></div></div></section><section className="mx-auto max-w-7xl px-5 py-20 lg:px-8 lg:py-28"><SectionHeading eyebrow={t("home.meetTeachers")} title={t("home.teacherTitle")} copy={t("home.teacherCopy")} action={<Button href="/teachers" variant="quiet">{t("home.meetAll")} <ArrowRight size={16}/></Button>}/><div className="grid gap-5 lg:grid-cols-3">{instructors.map((instructor, i) => <TutorCard key={instructor.slug} instructor={instructor} index={i}/>)}</div></section><section className="mx-auto max-w-7xl px-5 pb-24 lg:px-8"><div className="relative overflow-hidden rounded-[2rem] bg-[var(--ni-sage-soft)] px-7 py-12 lg:px-16 lg:py-16"><div className="star-watermark absolute -right-8 -top-12 h-64 w-64 opacity-60"/><div className="relative max-w-2xl"><Pill tone="gold">{t("home.noorWay")}</Pill><h2 className="mt-5 font-display text-5xl leading-tight text-[var(--ni-ink)]">{t("home.nextTitle")}</h2><p className="mt-4 text-base leading-7 text-[var(--ni-muted)]">{t("home.nextCopy")}</p><div className="mt-7 flex flex-wrap gap-3"><Button href="/requirements">{t("home.postRequirement")} <ArrowRight size={16}/></Button><Button href="/how-it-works" variant="outline">{t("home.seeHow")}</Button></div></div></div></section></main><Footer/></>; }
function Filters({ onChange, placeholder }: { onChange: (value: string) => void; placeholder?: string }) { const { t } = useLocale(); return <div className="flex flex-col gap-3 rounded-2xl border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-3 shadow-sm md:flex-row"><div className="flex flex-1 items-center gap-3 rounded-xl bg-[var(--ni-sage-soft)] px-4"><Search size={18} className="text-[var(--ni-muted-soft)]"/><input aria-label={t("catalogue.search")} onChange={(e) => onChange(e.target.value)} placeholder={placeholder || t("catalogue.search")} className="w-full bg-transparent py-3 text-sm outline-none placeholder:text-[var(--ni-muted-soft)]"/></div><select className="rounded-xl bg-[var(--ni-sage-soft)] px-4 py-3 text-sm text-[var(--ni-moss-deep)] outline-none"><option>{t("catalogue.allSubjects")}</option>{categories.map((c) => <option key={c}>{c}</option>)}</select><select className="rounded-xl bg-[var(--ni-sage-soft)] px-4 py-3 text-sm text-[var(--ni-moss-deep)] outline-none"><option>{t("catalogue.allLevels")}</option><option>Beginner</option><option>Intermediate</option></select><button className="inline-flex items-center justify-center gap-2 rounded-xl border border-[var(--ni-sage-line)] px-4 py-3 text-sm font-bold text-[var(--ni-teal-soft)]"><Filter size={16}/>{t("catalogue.moreFilters")}</button></div>; }
function PageIntro({ eyebrow, title, copy }: { eyebrow: string; title: string; copy: string }) { return <section className="bg-[var(--ni-bg)]"><div className="mx-auto max-w-7xl px-5 py-14 lg:px-8 lg:py-20"><p className="text-xs font-bold uppercase tracking-[.2em] text-[var(--ni-gold-ink)]">{eyebrow}</p><h1 className="mt-4 max-w-3xl font-display text-6xl leading-[.98] tracking-tight text-[var(--ni-teal)]">{title}</h1><p className="mt-5 max-w-2xl text-lg leading-8 text-[var(--ni-muted)]">{copy}</p></div></section>; }
function CoursesPage({ initialSubject = "" }: { initialSubject?: string }) {
  const { t } = useLocale();
  const [query, setQuery] = useState("");
  const coursesQuery = trpc.schedulingPublic.publishedCourses.useQuery(undefined, { retry: false });
  type PublicCourseRow = { id: string; slug: string; title: string; description: string; subject: string; level: string; language: string; status: string; created_at: string };
  const liveCourses: PublicCourseRow[] = coursesQuery.data?.ok ? coursesQuery.data.data as PublicCourseRow[] : [];
  const filtered = liveCourses.filter((course) => (!initialSubject || course.subject.toLowerCase() === initialSubject.toLowerCase()) && `${course.title} ${course.subject} ${course.description} ${course.language}`.toLowerCase().includes(query.toLowerCase()));
  return <><Header/><PageIntro eyebrow={t("catalogue.eyebrow")} title={t("catalogue.title")} copy={t("catalogue.copy")}/><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><Filters onChange={setQuery}/>{coursesQuery.isLoading && <p className="mt-8 rounded-2xl bg-[var(--ni-sage-soft)] p-5 text-sm text-[var(--ni-muted)]">{t("catalogue.loadingPublished")}</p>}{coursesQuery.isError && <p className="mt-8 rounded-2xl bg-[var(--ni-clay-soft)] p-5 text-sm text-[var(--ni-clay)]" role="alert">{t("catalogue.courseDiscoveryUnavailable")}</p>}{!coursesQuery.isLoading && !coursesQuery.isError && <><div className="mb-7 mt-10 flex items-center justify-between"><p className="text-sm font-semibold text-[var(--ni-muted)]">{t("catalogue.publishedCourses")} · {filtered.length}</p><span className="text-xs text-[var(--ni-muted-soft)]">{t("catalogue.publicFieldsOnly")}</span></div>{filtered.length ? <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{filtered.map((course, index) => <Link key={course.id} href={`/courses/${course.slug}`} className="group overflow-hidden rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] shadow-[0_14px_40px_rgba(37,77,60,.06)] hover:-translate-y-1"><div className="relative h-36 overflow-hidden" style={{ backgroundColor: index % 2 ? "var(--ni-sage-soft)" : "var(--ni-gold-soft)" }}><img src={courseVisuals[index % courseVisuals.length]} alt="" className="h-full w-full object-cover mix-blend-multiply opacity-75"/><div className="absolute left-4 top-4"><Pill>{course.subject}</Pill></div></div><div className="p-5"><div className="mb-3 flex items-center justify-between text-xs text-[var(--ni-muted)]"><span>{course.level}</span><span>{course.language}</span></div><h3 className="font-display text-2xl leading-tight text-[var(--ni-ink)]">{course.title}</h3><p className="mt-3 line-clamp-3 text-sm leading-6 text-[var(--ni-muted)]">{course.description}</p><div className="mt-5 border-t border-[var(--ni-sage-soft)] pt-4 text-xs font-semibold text-[var(--ni-sage-ink)]">Published course · {course.status}</div></div></Link>)}</div> : <EmptyState title={t("catalogue.noneTitle")} copy={t("catalogue.noneCopy")}/>}</>}</main><Footer/></>;
}

function CourseDetail({ slug }: { slug: string }) {
  const { t } = useLocale();
  const courseQuery = trpc.schedulingPublic.courseBySlug.useQuery({ slug }, { retry: false });
  type PublicCourseDetail = { id: string; slug: string; title: string; description: string; subject: string; level: string; language: string; status: string; created_at: string };
  const course: PublicCourseDetail | null = courseQuery.data?.ok ? courseQuery.data.data as PublicCourseDetail : null;
  if (courseQuery.isLoading) return <><Header/><main className="mx-auto max-w-5xl px-5 py-20"><p className="rounded-2xl bg-[var(--ni-sage-soft)] p-5 text-sm text-[var(--ni-muted)]">Loading the approved course…</p></main><Footer/></>;
  if (courseQuery.isError || !course) return <><Header/><main className="mx-auto max-w-5xl px-5 py-20"><p className="text-xs font-bold uppercase tracking-[.2em] text-[var(--ni-gold-ink)]">Course details</p><h1 className="mt-4 font-display text-5xl">{t("catalogue.courseNotPublic")}</h1><p className="mt-4 max-w-2xl text-[var(--ni-muted)]">{t("catalogue.courseNotPublicCopy")}</p><Link href="/courses" className="mt-7 inline-flex rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-semibold text-white">{t("courseDetail.back")}</Link></main><Footer/></>;
  return <><Header/><main><div className="bg-[var(--ni-teal)] text-white"><div className="mx-auto max-w-7xl px-5 py-14 lg:px-8 lg:py-20"><Link href="/courses" className="text-sm text-[var(--ni-sage-line)]">← {t("courseDetail.back")}</Link><div className="mt-12 grid gap-12 lg:grid-cols-[1fr_.75fr]"><div><Pill tone="gold">{course.subject}</Pill><h1 className="mt-6 max-w-2xl font-display text-6xl leading-[.96]">{course.title}</h1><p className="mt-6 max-w-xl text-lg leading-8 text-[var(--ni-sage-line)]">{course.description}</p><div className="mt-8 flex flex-wrap gap-3"><Button href="/login">{t("courseDetail.enrol")} <ArrowRight size={16}/></Button><TrialCTA context={{ courseSlug: course.slug }} label={t("courseDetail.requestTrial")}/></div></div><div className="overflow-hidden rounded-[2rem] bg-[var(--ni-sage-soft)] p-3"><img src={courseArt} alt="" className="h-72 w-full rounded-[1.5rem] object-cover"/></div></div></div></div><div className="mx-auto grid max-w-7xl gap-12 px-5 py-16 lg:grid-cols-[1.1fr_.7fr] lg:px-8"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[var(--ni-gold-ink)]">{t("courseDetail.outline")}</p><h2 className="mt-3 font-display text-4xl text-[var(--ni-ink)]">{t("courseDetail.sequence")}</h2><div className="mt-8 rounded-2xl border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6 text-sm leading-7 text-[var(--ni-muted)]">Published course content is available through the connected course workspace. Lesson and module data will appear here when the protected course-content query is connected.</div></div><aside className="rounded-[1.5rem] bg-[var(--ni-sage-soft)] p-7"><p className="text-xs font-bold uppercase tracking-[.18em] text-[var(--ni-gold-ink)]">{t("courseDetail.glance")}</p><div className="mt-6 space-y-5 text-sm"><Info label={t("courseDetail.level")} value={course.level}/><Info label={t("courseDetail.language")} value={course.language}/><Info label={t("courseDetail.instructor")} value="Instructor profile to be connected"/><Info label={t("courseDetail.format")} value="Course format to be connected"/></div><div className="mt-7 border-t border-[var(--ni-sage-line)] pt-5 text-sm leading-6 text-[var(--ni-muted)]"><ShieldCheck size={17} className="mb-2 text-[var(--ni-gold-ink)]"/>{t("courseDetail.trust")}</div></aside></div></main><Footer/></>;
}

function TeachersPage({ initialSubject = "" }: { initialSubject?: string }) {
  const { t } = useLocale();
  const [filters, setFilters] = useState<MarketplaceFilterState>({ ...emptyFilters, subjects: initialSubject ? [initialSubject] : [] });
  const [page, setPage] = useState(0);
  const pageSize = 12;

  // Every filter is sent to the server; the browser never narrows the list itself.
  const instructorsQuery = trpc.schedulingPublic.instructors.useQuery({
    query: filters.query || undefined,
    subjects: filters.subjects.length ? filters.subjects : undefined,
    languages: filters.languages.length ? filters.languages : undefined,
    levels: filters.levels.length ? filters.levels : undefined,
    minRateMinor: filters.minRateMinor,
    maxRateMinor: filters.maxRateMinor,
    minYearsExperience: filters.minYearsExperience,
    sort: filters.sort as "relevance" | "rate_asc" | "rate_desc" | "experience_desc",
    limit: pageSize,
    offset: page * pageSize,
  }, { retry: false });
  const facetsQuery = trpc.schedulingPublic.instructorFacets.useQuery(undefined, { retry: false });

  type PublicInstructorRow = {
    user_id?: string; public_slug: string; subjects: string[] | null; teaching_levels: string[] | null;
    teaching_languages: string[] | null; years_experience: number | null; teaching_approach: string | null;
    hourly_rate_minor: number | null; currency: string | null; availability_summary: string | null;
    public_profile_status: string; verification_status: string;
  };
  const result = instructorsQuery.data?.ok ? instructorsQuery.data.data as { instructors: PublicInstructorRow[]; total: number } : null;
  const instructors = result?.instructors ?? [];
  const total = result?.total ?? 0;
  const facets = facetsQuery.data?.ok ? facetsQuery.data.data as { subjects: string[]; languages: string[]; levels: string[] } : { subjects: [], languages: [], levels: [] };

  const updateFilters = (nextFilters: MarketplaceFilterState) => { setFilters(nextFilters); setPage(0); };
  const rate = (minor: number | null, currency: string | null) =>
    typeof minor === "number" ? (minor / 100).toFixed(2) + " " + (currency || "USD") : t("marketplace.rateOnRequest");

  return <><Header/><PageIntro eyebrow={t("teachers.eyebrow")} title={t("teachers.title")} copy={t("teachers.copy")}/>
    <main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16">
      <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-center">
        <label className="flex-1">
          <span className="sr-only">{t("teachers.search")}</span>
          <input
            type="search" value={filters.query} placeholder={t("teachers.search")}
            onChange={(event) => updateFilters({ ...filters, query: event.target.value })}
            className="w-full rounded-full border border-[var(--ni-sage-line)] bg-[var(--ni-field)] px-5 py-3 text-sm text-[var(--ni-ink)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--ni-moss)]"
          />
        </label>
        <MarketplaceFilters variant="trigger" value={filters} onChange={updateFilters} facets={facets} resultCount={total} showRate showExperience sortOptions={[
            { value: "relevance", label: t("marketplace.sortRelevance") },
            { value: "rate_asc", label: t("marketplace.sortRateAsc") },
            { value: "rate_desc", label: t("marketplace.sortRateDesc") },
            { value: "experience_desc", label: t("marketplace.sortExperience") },
          ]}/>
      </div>

      <div className="grid gap-8 lg:grid-cols-[16rem_1fr]">
        <MarketplaceFilters variant="sidebar" value={filters} onChange={updateFilters} facets={facets} resultCount={total} showRate showExperience sortOptions={[
            { value: "relevance", label: t("marketplace.sortRelevance") },
            { value: "rate_asc", label: t("marketplace.sortRateAsc") },
            { value: "rate_desc", label: t("marketplace.sortRateDesc") },
            { value: "experience_desc", label: t("marketplace.sortExperience") },
          ]}/>

        <div className="min-w-0">
          {instructorsQuery.isLoading && <p className="rounded-2xl bg-[var(--ni-sage-soft)] p-5 text-sm text-[var(--ni-muted)]" aria-live="polite">{t("catalogue.loadingApprovedInstructors")}</p>}
          {instructorsQuery.isError && <p role="alert" className="rounded-2xl bg-[var(--ni-clay-soft)] p-5 text-sm text-[var(--ni-clay)]">{t("catalogue.instructorDiscoveryUnavailable")}</p>}
          {!instructorsQuery.isLoading && !instructorsQuery.isError && <>
            <div className="mb-5 flex flex-wrap items-center justify-between gap-2">
              <p className="text-sm font-semibold text-[var(--ni-muted)]">{t("catalogue.approvedInstructors")} · <span className="tabular">{total}</span></p>
              <span className="text-xs text-[var(--ni-muted-soft)]">{t("catalogue.publishedApprovedOnly")}</span>
            </div>
            {instructors.length ? <>
              <div className="stagger grid gap-5 xl:grid-cols-2">
                {instructors.map((instructor) => <Link key={instructor.public_slug} href={"/teachers/" + instructor.public_slug}
                  className="lift group block rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-5 outline-none focus-visible:ring-2 focus-visible:ring-[var(--ni-moss)]">
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0">
                      <p className="truncate font-display text-xl text-[var(--ni-ink)]">{instructor.public_slug}</p>
                      <p className="mt-1 text-xs font-bold uppercase tracking-[.12em] text-[var(--ni-gold-ink)]">
                        {typeof instructor.years_experience === "number" ? t("marketplace.yearsExperience", { years: String(instructor.years_experience) }) : t("marketplace.experienceNotStated")}
                      </p>
                    </div>
                    <span className="status-pill shrink-0 rounded-full bg-[var(--ni-sage-soft)] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.1em] text-[var(--ni-moss-deep)]">{t("marketplace.verified")}</span>
                  </div>
                  {instructor.teaching_approach && <p className="mt-3 text-sm leading-6 text-[var(--ni-muted)]">{instructor.teaching_approach}</p>}
                  <dl className="mt-4 grid grid-cols-2 gap-3 text-xs">
                    <div><dt className="text-[var(--ni-muted-soft)]">{t("marketplace.subject")}</dt><dd className="mt-0.5 truncate font-semibold text-[var(--ni-ink)]">{(instructor.subjects ?? []).join(", ") || "—"}</dd></div>
                    <div><dt className="text-[var(--ni-muted-soft)]">{t("marketplace.language")}</dt><dd className="mt-0.5 truncate font-semibold text-[var(--ni-ink)]">{(instructor.teaching_languages ?? []).join(", ") || "—"}</dd></div>
                    <div><dt className="text-[var(--ni-muted-soft)]">{t("marketplace.level")}</dt><dd className="mt-0.5 truncate font-semibold text-[var(--ni-ink)]">{(instructor.teaching_levels ?? []).join(", ") || "—"}</dd></div>
                    <div><dt className="text-[var(--ni-muted-soft)]">{t("marketplace.hourlyRate")}</dt><dd className="mt-0.5 truncate font-semibold text-[var(--ni-moss)] tabular ltr-embed">{rate(instructor.hourly_rate_minor, instructor.currency)}</dd></div>
                  </dl>
                  {instructor.availability_summary && <p className="mt-3 truncate text-xs text-[var(--ni-muted-soft)]">{instructor.availability_summary}</p>}
                </Link>)}
              </div>
              {total > pageSize && <nav className="mt-8 flex items-center justify-between gap-3" aria-label={t("marketplace.pagination")}>
                <Button type="button" variant="outline" disabled={page === 0} onClick={() => setPage((value) => Math.max(0, value - 1))}>{t("marketplace.previous")}</Button>
                <p className="text-xs text-[var(--ni-muted)] tabular">{t("marketplace.pageOf", { page: String(page + 1), pages: String(Math.max(1, Math.ceil(total / pageSize))) })}</p>
                <Button type="button" variant="outline" disabled={(page + 1) * pageSize >= total} onClick={() => setPage((value) => value + 1)}>{t("marketplace.next")}</Button>
              </nav>}
            </> : <div className="rounded-[1.35rem] border border-dashed border-[var(--ni-sage-mid)] bg-[var(--ni-sage-soft)] px-6 py-12 text-center">
              <h3 className="font-display text-2xl text-[var(--ni-ink)]">{t("marketplace.noMatches")}</h3>
              <p className="mx-auto mt-2 max-w-md text-sm leading-6 text-[var(--ni-muted)]">{t("marketplace.noMatchesCopy")}</p>
              <button type="button" onClick={() => updateFilters({ ...emptyFilters })} className="mt-5 rounded-full bg-[var(--ni-moss)] px-5 py-2.5 text-sm font-semibold text-white">{t("marketplace.clearFilters")}</button>
            </div>}
          </>}
        </div>
      </div>
    </main><Footer/></>;
}

